  const cards = "<article id=\"entry-dgp-341\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγρη</h1><div class=\"entry-meta\"><span>DGP · ordem 341 na letra α · nº geral 341</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">jôn. = ἄγρα.</p></section></article>\n<article id=\"entry-dgp-342\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριαίνω</h1><div class=\"entry-meta\"><span>DGP · ordem 342 na letra α · nº geral 342</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀγριανῶ, aor. ἠγρίανα, perf. desus.) 1 irritar-se; enfurecer-se 2 (animal) ser ou tornar-se selvagem 3 enfurecer; irritar. 〈ἄγριος〉</p></section></article>\n<article id=\"entry-dgp-343\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριέλαιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 343 na letra α · nº geral 343</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de oliveira selvagem ♦ ἡ ἀγριέλαιος 2 oliveira selvagem. 〈ἄγριος, ἐλαία〉</p></section></article>\n<article id=\"entry-dgp-344\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγριος, α</h1><div class=\"entry-meta\"><span>DGP · ordem 344 na letra α · nº geral 344</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ος, ον 1 selvagem; agreste; silvestre 2 selvagem; rude; violento 3 rústico; inculto (lugar) ♦ ἄγρια adv. 4 de maneira selvagem ♦ τὸ ἄγριον 5 selvageria. 〈ἀγρός〉</p></section></article>\n<article id=\"entry-dgp-345\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριότης, ητος (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 345 na letra α · nº geral 345</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 estado selvagem (de animais, plantas, terras) 2 selvageria; crueldade (de homens). 〈ἄγριος〉</p></section></article>\n<article id=\"entry-dgp-346\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριόφωνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 346 na letra α · nº geral 346</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de voz selvagem. 〈ἄγριος, φωνή〉</p></section></article>\n<article id=\"entry-dgp-347\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριόω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 347 na letra α · nº geral 347</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(3ª sing. aor. ἠγρίωσε) 1 tornar selvagem; exasperar; incitar alguém, ac., contra outrem, dat. ou πρός e ac. ♦ pas. 2 (planta, região) ser selvagem, inculto 3 (homem) ser selvagem, cruel. 〈ἄγριος〉</p></section></article>\n<article id=\"entry-dgp-348\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀγρίππας, α (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 348 na letra α · nº geral 348</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bíbl. Agripa, n. romano.</p></section></article>\n<article id=\"entry-dgp-349\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγριωπός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 349 na letra α · nº geral 349</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de aspecto ou olhar feroz. 〈ἄγριος, ὤψ〉</p></section></article>\n<article id=\"entry-dgp-350\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρίως</h1><div class=\"entry-meta\"><span>DGP · ordem 350 na letra α · nº geral 350</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 de maneira selvagem 2 de modo inculto.</p></section></article>\n<article id=\"entry-dgp-351\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγροβάτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 351 na letra α · nº geral 351</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que caminha nos campos. 〈ἀγρός, βαίνω〉</p></section></article>\n<article id=\"entry-dgp-352\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγροβότης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 352 na letra α · nº geral 352</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">que apascenta nos campos. 〈ἀγρός, βόσκω〉</p></section></article>\n<article id=\"entry-dgp-353\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρόθε</h1><div class=\"entry-meta\"><span>DGP · ordem 353 na letra α · nº geral 353</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἀγρόθεν adv. vindo do campo. 〈ἀγρός〉</p></section></article>\n<article id=\"entry-dgp-354\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγροικία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 354 na letra α · nº geral 354</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rusticidade 2 estada no campo 3 habitação no campo. 〈ἀγροῖκος〉</p></section></article>\n<article id=\"entry-dgp-355\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγροικίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 355 na letra α · nº geral 355</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. ἠγροικισάμην, part. perf. ἠγροι­κισμένος) comportar-se como camponês; comportar-se rusticamente; ser grosseiro. 〈ἀγροῖκος〉</p></section></article>\n<article id=\"entry-dgp-356\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγροῖκος</h1><div class=\"entry-meta\"><span>DGP · ordem 356 na letra α · nº geral 356</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἄγροικος, ος, ον 1 que vive no campo; agreste 2 rústico; grosseiro 3 inculto (lugar) 4 silvestre (fruta). 〈ἀγρός, οἰκέω〉</p></section></article>\n<article id=\"entry-dgp-357\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγροίκως</h1><div class=\"entry-meta\"><span>DGP · ordem 357 na letra α · nº geral 357</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. à maneira de camponês; rusticamente; grosseiramente.</p></section></article>\n<article id=\"entry-dgp-358\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγροιώτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 358 na letra α · nº geral 358</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 homem do campo; camponês ♦ adj. 2 rústico; grosseiro. 〈ἀγρός〉</p></section></article>\n<article id=\"entry-dgp-359\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρόμενος</h1><div class=\"entry-meta\"><span>DGP · ordem 359 na letra α · nº geral 359</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">part. aor.2 méd. sinc. de ἀγείρω.</p></section></article>\n<article id=\"entry-dgp-360\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρόνδε</h1><div class=\"entry-meta\"><span>DGP · ordem 360 na letra α · nº geral 360</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. em direção ao campo. 〈ἀγρός〉</p></section></article>\n<article id=\"entry-dgp-361\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρονόμος, ος</h1><div class=\"entry-meta\"><span>DGP · ordem 361 na letra α · nº geral 361</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e η, ον 1 do campo; agreste♦ ὁ ἀγρονόμος 2 agrônomo, fiscal da zona rural. 〈ἀγρός, νέμω〉</p></section></article>\n<article id=\"entry-dgp-362\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 362 na letra α · nº geral 362</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 campo; terra para cultivo 2 campo, em op. a cidade.</p></section></article>\n<article id=\"entry-dgp-363\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀγροτέρα, ας</h1><div class=\"entry-meta\"><span>DGP · ordem 363 na letra α · nº geral 363</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fem.) 1 Caçadora, epít. de Ártemis 2 que persegue: ἀ. μέριμνα pínd. preocupação em busca de alguma coisa. 〈ἄγρα〉</p></section></article>\n<article id=\"entry-dgp-364\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρότερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 364 na letra α · nº geral 364</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 campestre; silvestre; agreste 2 campesino (pessoa). 〈ἀγρός〉</p></section></article>\n<article id=\"entry-dgp-365\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρότης1, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 365 na letra α · nº geral 365</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">caçador. 〈ἄγρα〉</p></section></article>\n<article id=\"entry-dgp-366\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρότης2, ου</h1><div class=\"entry-meta\"><span>DGP · ordem 366 na letra α · nº geral 366</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(masc.) campestre; rústico. 〈ἀγρός〉</p></section></article>\n<article id=\"entry-dgp-367\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρυπνέω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 367 na letra α · nº geral 367</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀγρυπνήσω, aor. ἠγρύπνησα, perf. ἠγρύπνηκα) 1 não dormir; permanecer insone 2 ficar de vigília; velar. 〈ἄγρυπνος〉</p></section></article>\n<article id=\"entry-dgp-368\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρυπνητικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 368 na letra α · nº geral 368</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">desperto; vigilante. 〈ἀγρυπνέω〉</p></section></article>\n<article id=\"entry-dgp-369\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρυπνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 369 na letra α · nº geral 369</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 insônia; vigília 2 tempo de vigília; guarda 3 vigilância; preocupação. 〈ἄγρυπνος〉</p></section></article>\n<article id=\"entry-dgp-370\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγρυπνος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 370 na letra α · nº geral 370</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 sem sono; insone; vigilante 2 que afasta o sono; que mantém desperto ♦ τὸ ἄγρυπνον 3 vigília. 〈ἄγρα, ὕπνος〉</p></section></article>\n<article id=\"entry-dgp-371\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγρώσσω</h1><div class=\"entry-meta\"><span>DGP · ordem 371 na letra α · nº geral 371</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(só pres.) caçar; pescar. 〈ἄγρα〉</p></section></article>\n<article id=\"entry-dgp-372\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγρωστις, εως</h1><div class=\"entry-meta\"><span>DGP · ordem 372 na letra α · nº geral 372</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ίδος (ἡ) 1 erva em geral 2 escalracho, gramínea nociva. 〈ἀγρός〉</p></section></article>\n<article id=\"entry-dgp-373\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγυιά</h1><div class=\"entry-meta\"><span>DGP · ordem 373 na letra α · nº geral 373</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἄγυια, ας (ἡ) 1 via; rua 2 praça; quarteirão 3 cidade. 〈ἄγω〉</p></section></article>\n<article id=\"entry-dgp-374\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγυιάτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 374 na letra α · nº geral 374</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀγυιεύς.</p></section></article>\n<article id=\"entry-dgp-375\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγυιεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 375 na letra α · nº geral 375</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 protetor dos caminhos, epít. de Apolo 2 altar ou estela erguidos nas portas das casas, em honra de Apolo. 〈ἀγυιά〉</p></section></article>\n<article id=\"entry-dgp-376\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγύμναστος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 376 na letra α · nº geral 376</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 não exercitado em; inexperiente em, gen., εἰς, περί ou πρός e ac. 2 não provado pela dor. 〈ἀ-, γυμνάζω〉</p></section></article>\n<article id=\"entry-dgp-377\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγυμνάστως</h1><div class=\"entry-meta\"><span>DGP · ordem 377 na letra α · nº geral 377</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. sem exercício.</p></section></article>\n<article id=\"entry-dgp-378\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγυρις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 378 na letra α · nº geral 378</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aglomeração; multidão. 〈ἀγορά〉</p></section></article>\n<article id=\"entry-dgp-379\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγυρμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 379 na letra α · nº geral 379</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 coleta 2 reunião. 〈ἀγείρω〉</p></section></article>\n<article id=\"entry-dgp-380\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγυρτάζω</h1><div class=\"entry-meta\"><span>DGP · ordem 380 na letra α · nº geral 380</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">recolher; juntar; reunir. 〈ἀγύρτης〉</p></section></article>\n<article id=\"entry-dgp-381\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγύρτης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 381 na letra α · nº geral 381</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 mendigo 2 vagabundo 3 charlatão. 〈ἀγείρω〉</p></section></article>\n<article id=\"entry-dgp-382\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγυρτικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 382 na letra α · nº geral 382</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 de vagabundo 2 de charlatão. 〈ἀγύρ­της〉</p></section></article>\n<article id=\"entry-dgp-383\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγύρτρια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 383 na letra α · nº geral 383</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mendiga. 〈ἀγύρτης〉</p></section></article>\n<article id=\"entry-dgp-384\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχέμαχος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 384 na letra α · nº geral 384</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que combate de perto 2 bom para combater de perto (arma). 〈ἄγχι, μάχομαι〉</p></section></article>\n<article id=\"entry-dgp-385\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγχι</h1><div class=\"entry-meta\"><span>DGP · ordem 385 na letra α · nº geral 385</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(comp. ἆσσον, superl. ἄγχιστα) adv. 1 (lugar) perto 2 (tempo) quase ♦ prep. 3 perto de; próximo de, gen.</p></section></article>\n<article id=\"entry-dgp-386\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιάλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 386 na letra α · nº geral 386</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vizinho do mar. 〈ἄγχι, ἅλς〉</p></section></article>\n<article id=\"entry-dgp-387\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιβαθής, ής, ές</h1><div class=\"entry-meta\"><span>DGP · ordem 387 na letra α · nº geral 387</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 profundo desde a beira; profundo 2 alto desde a beira (margem). 〈ἄγχι, βάθος〉</p></section></article>\n<article id=\"entry-dgp-388\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιγείτων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 388 na letra α · nº geral 388</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος vizinho.</p></section></article>\n<article id=\"entry-dgp-389\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχίθεος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 389 na letra α · nº geral 389</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 semelhante a um deus; quase deus 2 crist. próximo de Deus ♦ ὁ ἀγχίθεος 3 semideus. 〈ἄγχι, θεός〉</p></section></article>\n<article id=\"entry-dgp-390\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχίθυρος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 390 na letra α · nº geral 390</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vizinho de porta. 〈ἄγχι, θύρα〉</p></section></article>\n<article id=\"entry-dgp-391\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιμαχητής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 391 na letra α · nº geral 391</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀγχέμαχος.</p></section></article>\n<article id=\"entry-dgp-392\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχίμολος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 392 na letra α · nº geral 392</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que vem logo após; que se avizinha; ἐξ ἀγχιμόλοιο de bem perto ♦ ἀγχίμολον adv. 2 bem perto de, dat. 〈ἄγχι, μολεῖν〉</p></section></article>\n<article id=\"entry-dgp-393\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχίνοια, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 393 na letra α · nº geral 393</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">vivacidade de espírito; perspicácia. 〈ἀγχίνοος〉</p></section></article>\n<article id=\"entry-dgp-394\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχίνοος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 394 na letra α · nº geral 394</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de espírito vivo; perspicaz. 〈ἄγχι, νόος〉</p></section></article>\n<article id=\"entry-dgp-395\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχίπλοος-ους, οος-ους, οον-ουν</h1><div class=\"entry-meta\"><span>DGP · ordem 395 na letra α · nº geral 395</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">de navegação curta; de travessia curta. 〈ἄγχι, πλέω〉</p></section></article>\n<article id=\"entry-dgp-396\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχίπολις, ιος</h1><div class=\"entry-meta\"><span>DGP · ordem 396 na letra α · nº geral 396</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">e ἀγχίπτολις, εως (masc., fem.) 1 protetor da cidade 2 vizinho da cidade. 〈ἄγχι, πόλις〉</p></section></article>\n<article id=\"entry-dgp-397\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀγχίσης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 397 na letra α · nº geral 397</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">Anquises, pai de Enéias.</p></section></article>\n<article id=\"entry-dgp-398\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἀγχισιάδης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 398 na letra α · nº geral 398</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">filho de Anquises. 〈Ἀγχίσης〉</p></section></article>\n<article id=\"entry-dgp-399\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγχιστα</h1><div class=\"entry-meta\"><span>DGP · ordem 399 na letra α · nº geral 399</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">cf. ἄγχιστος.</p></section></article>\n<article id=\"entry-dgp-400\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιστεία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 400 na letra α · nº geral 400</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parentesco próximo 2 familiaridade; intimidade 3 direito de herança. 〈ἀγχιστεύω〉</p></section></article>\n<article id=\"entry-dgp-401\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιστεῖον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 401 na letra α · nº geral 401</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀγχιστεία.</p></section></article>\n<article id=\"entry-dgp-402\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιστεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 402 na letra α · nº geral 402</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 parente próximo 2 herdeiro legítimo. 〈ἄγχιστος〉</p></section></article>\n<article id=\"entry-dgp-403\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιστεύω</h1><div class=\"entry-meta\"><span>DGP · ordem 403 na letra α · nº geral 403</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(aor. pas. ἠγχιστεύθην) 1 ser próximo; ser vizinho de, gen. ou dat. 2 ser parente próximo de; ser herdeiro legítimo de alguém, dat. 3 bíbl. exercer o direito de parente e tomar posse de herança. 〈ἀγχιστεύς〉</p></section></article>\n<article id=\"entry-dgp-404\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιστήρ, ῆρος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 404 na letra α · nº geral 404</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">aquele que é causa de, gen. 〈ἄγχι〉</p></section></article>\n<article id=\"entry-dgp-405\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιστῖνος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 405 na letra α · nº geral 405</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">bem próximo; no pl. cerrados uns aos outros. 〈ἄγχιστος〉</p></section></article>\n<article id=\"entry-dgp-406\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγχιστος, η, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 406 na letra α · nº geral 406</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 bem próximo; vizinho 2 próximo (pela origem); parente próximo ♦ ἄγχιστον, ἄγχιστα adv. 3 (lugar) bem próximo; o mais próximo; de muito perto 4 (tempo) recentemente. 〈ἄγχι〉</p></section></article>\n<article id=\"entry-dgp-407\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχίστροφος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 407 na letra α · nº geral 407</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 rápido em virar-se; versátil ♦ ἀγχίστροφα adv. 2 de maneira versátil. 〈ἄγχι, στρέφω〉</p></section></article>\n<article id=\"entry-dgp-408\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχιτέρμων, ων, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 408 na letra α · nº geral 408</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">gen. ονος limítrofe; vizinho. 〈ἄγχι, τέρμα〉</p></section></article>\n<article id=\"entry-dgp-409\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχόθεν</h1><div class=\"entry-meta\"><span>DGP · ordem 409 na letra α · nº geral 409</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. vindo de bem perto. 〈ἄγχι〉</p></section></article>\n<article id=\"entry-dgp-410\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχόθι</h1><div class=\"entry-meta\"><span>DGP · ordem 410 na letra α · nº geral 410</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 bem perto ♦ prep. 2 bem perto de, gen. 〈ἄγχι〉</p></section></article>\n<article id=\"entry-dgp-411\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχόνη, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 411 na letra α · nº geral 411</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 laço; corda para estrangular 2 estrangulamento; enforcamento 3 angústia. 〈ἄγχω〉</p></section></article>\n<article id=\"entry-dgp-412\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχότατα, ἀγχοτάτω</h1><div class=\"entry-meta\"><span>DGP · ordem 412 na letra α · nº geral 412</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">ἀγχοῦ.</p></section></article>\n<article id=\"entry-dgp-413\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχότερος, α, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 413 na letra α · nº geral 413</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">o mais próximo; bem próximo de, gen. 〈ἄγχι〉</p></section></article>\n<article id=\"entry-dgp-414\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχοῦ</h1><div class=\"entry-meta\"><span>DGP · ordem 414 na letra α · nº geral 414</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. 1 próximo; bem perto 2 de igual modo; semelhantemente ♦ prep. 3 perto de, gen. ou dat. 〈ἄγχι〉</p></section></article>\n<article id=\"entry-dgp-415\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγχουσα, ης (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 415 na letra α · nº geral 415</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 ancusa, planta 2 corante para o rosto extraído da raiz da ancusa, ruge. 〈ἄγχω〉</p></section></article>\n<article id=\"entry-dgp-416\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγχω</h1><div class=\"entry-meta\"><span>DGP · ordem 416 na letra α · nº geral 416</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἄγξω, aor. ἦγξα, perf. desus.) 1 apertar; sufocar; estrangular ♦ méd. 2 enforcar-se.</p></section></article>\n<article id=\"entry-dgp-417\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχώμαλος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 417 na letra α · nº geral 417</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 quase igual: ἐγένοντο ἀγχώμαλοι ἐν τῇ χειροτονίᾳ tuc. ficaram quase iguais na votação 2 incerto; duvidoso: ἀ. μάχη tuc. combate incerto, ἐν ἀγχωμάλῳ sem resultado decisivo ♦ ἀγχώμαλα adv. 3 de maneira equilibrada; de chances quase iguais: ἀ. ναυμαχεῖν tuc. realizar combate naval em condições quase iguais, i.e., com equilíbrio de forças. 〈ἄγχι, ὁμαλός〉</p></section></article>\n<article id=\"entry-dgp-418\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγχωμάλως</h1><div class=\"entry-meta\"><span>DGP · ordem 418 na letra α · nº geral 418</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com oportunidades quase iguais.</p></section></article>\n<article id=\"entry-dgp-419\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄγω</h1><div class=\"entry-meta\"><span>DGP · ordem 419 na letra α · nº geral 419</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἄξω, aor.2 ἤγαγον, rar. aor.1 ἦξα, perf. ἦχα; pas. fut. ἀχθήσομαι ou ἄξομαι, aor. ἤχθην, perf. ἦγμαι) ativa 1 conduzir; levar; trazer 2 levar sob constrangimento, levar à força, arrastar 3 levar em saque; saquear 4 conduzir para si, atrair 5 dirigir, guiar, educar (pessoas) 6 prolongar; estender; alongar (coisas) 7 conduzir no tempo; fazer durar; manter; celebrar 8 considerar, julgar 9 ter como peso, valer 10 intr. dirigir-se; ir; caminhar ♦ ἄγε e ἄγετε, imper. usado como interj. exort., eia! vamos! continue!, sobretudo nas loc. εἰ δ’ ἄγε, νῦν δ’ ἄγε, ἄγε δή, αλλ’ ἄγε, ἄγε νῦν média 11 levar ou trazer uma coisa para si ou para tê-la consigo 12 conduzir para casa como esposa, tomar por esposa, dar por esposa 1 σχιστὴ δ’ ὁδὸς ἐς ταὐτὸ Δελφῶν κἀπὸ Δαυλίας ἄγει sóf. uma estrada bifurcada vinda de Delfos e de Dáulia leva ao mesmo lugar, δῶκε δ’ ἄγειν ἑτάροισι ὑπερθύμοισι γυναῖκα hom. permitiu que seus destemidos companheiros levassem a mulher, ἄγω δ’αἴθωνα σίδηρον hom. trago o ferro luzente 2 ἐμέ τινες εἰς δίκας ἄγουσιν xen. alguns me levam aos tribunais, ἡ πεπρωμένη ἄγει θανεῖν ἀδελφὴν ἐμήν eur. o destino marcado leva minha irmã à morte, ὁ ἀγαγὼν αὐτὸν ἐπὶ τὸν ὅρκον plut. aquele que o constrangeu a jurar. 3 φέρων καὶ ἄγων τὴν Βιθυνίζα xen. carregando e levando toda a Bitínia, i.e., saqueando a Bitínia, ἦγον καὶ ἔκαιον xen. saqueavam e incendiavam 4 τί με πρὸς ναοὺς ἄγαγες; eur. por que me atraíste ao templo? λίθος τοὺς δακτυλίους ἄγει σιδηροῦς plat. a pedra atrai os anéis de ferro 5 ἄγει ψυχὴ πάντα τὰ κατ’ οὐρανὸν καὶ γῆν plat. uma alma dirige tudo o que está no céu e na terra, ἄγοντες τὴν πόλιν ἐν ὁμονοίᾳ dem. conduzindo a cidade em harmonia 6 ἧ ἐκεῖνοι ἔμελλον ἄξειν τὸ τεῖχος tuc. por onde iriam prolongar a muralha 7 ἄγοντες τὴν ἡμέραν ταύτην πάντα τὸν χρόνον tuc. fazendo este dia durar o tempo todo, ἄγοντας πρὸς Ἀθηναίους δεχημέρους σπονδάς tuc. observando uma trégua de dez dias com os atenienses, ἐλευθέραν ἦγε τὴν Ἑλλάδα dem. mantinha a Hélade livre, μούνη γὰρ ἄγειν οὐκέτι σωκῶ λύπης ἀντίρροπον ἄχθος sóf. sozinha não mais sou capaz de suportar um peso equivalente à minha dor, ἄγουσι τοὺς γάμους men. celebram as bodas 8 περὶ πλείστου ἦγον τὰ τοῦ θεοῦ πορσύνειν her. consideravam muito importante celebrar o culto do deus, ἃ μάλιστ’ ἦγεν ἐν τιμῇ plat. o que ele acima de tudo honrava 9 χρυσίδες τέτταρες ἄγουσα ἑκάστη μνᾶν dem. quatro vasos de ouro, pesando cada um uma mina, ὁ ἀκινάκης ἦγε τριακοσίους δαρεικούς dem. a cimitarra valia trezentos daricos 10 ἔλεγεν ὅτι ἤδη καιρὸς εἴη ἄγειν ἐπὶ τοὺς πολεμίους xen. dizia que já era hora de avançar contra os inimigos 11 ἴσασι γὰρ ἐφ’ οἷς αὐτοὺς Κυαξάρης ἄγεται συμμάχους xen. sabem sob que condições Ciáxares os levava como aliados, καὶ μ’ ἔφασαν χρυσόν τε καὶ ἄργυρον οἴκαδ’ ἄγεσθαι hom. diziam que eu estava levando para casa ouro e prata 12 γυναῖκα τεκνοποιὸν μὴ ἄγεσθαι ἐς τὰ οἰκία her. não levar para casa uma mulher que possa ter filhos, ὑεῖ δὲ Σπάρτηθεν Ἀλέκτορος ἤγετο κούρην hom. para seu filho trazia de Esparta como esposa a filha de Alector.</p></section></article>\n<article id=\"entry-dgp-420\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγῷ, ῇς, ῇ</h1><div class=\"entry-meta\"><span>DGP · ordem 420 na letra α · nº geral 420</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">subj. aor.2 pas. de ἄγνυμι.</p></section></article>\n<article id=\"entry-dgp-421\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγώ</h1><div class=\"entry-meta\"><span>DGP · ordem 421 na letra α · nº geral 421</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">crase de ἅ ἐγώ.</p></section></article>\n<article id=\"entry-dgp-422\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωγεύς, έως (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 422 na letra α · nº geral 422</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 condutor 2 correia; rédea. 〈ἄγω〉</p></section></article>\n<article id=\"entry-dgp-423\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωγή, ῆς (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 423 na letra α · nº geral 423</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 direção; condução 2 viagem 3 direcionamento; tendência 4 prisão por ordem judicial 5 educação; instrução 6 modo de conduzir (uma questão, negócios, as festas); conduta; método 7 modo de vida; comportamento 8 transporte (de coisas) 9 Mús. duração. 〈ἄγω〉</p></section></article>\n<article id=\"entry-dgp-424\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγώγιμος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 424 na letra α · nº geral 424</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 transportável (coisa) 2 passível de ser preso, de ser escravizado (pessoa) 3 suscetível de se deixar arrastar a; inclinado a, πρός e ac. ♦ τὸ ἀγώγιμον 4 encantamento; filtro de amor ♦ τὰ ἀγώγιμα 5 coisas transportáveis, mercadorias. 〈ἀγωγή〉</p></section></article>\n<article id=\"entry-dgp-425\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγώγιον, ου (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 425 na letra α · nº geral 425</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">mercadoria transportada; carregamento. 〈ἀγωγή〉</p></section></article>\n<article id=\"entry-dgp-426\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωγός, ός, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 426 na letra α · nº geral 426</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 que guia; que conduz 2 capaz de atrair; sedutor de, gen. ♦ ὁ ἀγωγός 3 condutor; guia. 〈ἄγω〉</p></section></article>\n<article id=\"entry-dgp-427\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγών, ῶνος (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 427 na letra α · nº geral 427</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 assembléia; reunião; conselho 2 jogo; competição; concurso 3 combate; luta 4 debate 5 litígio 6 interesse que leva à luta; luta espiritual ou mental 7 luta mortal; esforço penoso 8 lugar de reunião ou de jogos; campo; arena 9 Ret. veemência do discurso ou do argumento 10 Agón, divindade da competição. 〈ἄγω〉</p></section></article>\n<article id=\"entry-dgp-428\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνάρχης, ου (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 428 na letra α · nº geral 428</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">juiz da luta. 〈ἀγών, ἄρχω〉</p></section></article>\n<article id=\"entry-dgp-429\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 429 na letra α · nº geral 429</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 luta (em jogos); participação nos grandes jogos; concurso 2 exercício físico 3 inquietude; ansiedade; angústia 4 crist. agonia. 〈ἀγών〉</p></section></article>\n<article id=\"entry-dgp-430\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνιάω-ῶ</h1><div class=\"entry-meta\"><span>DGP · ordem 430 na letra α · nº geral 430</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀγωνιάσω, aor. ἠγωνίασα, perf. desus.) 1 lutar; competir 2 ter ansiedade; inquietar-se com algo, περί e gen., ἐπί e dat. 3 temer. 〈ἀγωνία〉</p></section></article>\n<article id=\"entry-dgp-431\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνίζομαι</h1><div class=\"entry-meta\"><span>DGP · ordem 431 na letra α · nº geral 431</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">(fut. ἀγωνιοῦμαι e ἀγωνίσομαι, aor. ἠγωνισάμην, perf. ἠγώνισμαι) 1 concorrer; disputar (em jogos) 2 lutar; combater por algo, περί e gen.; contra alguém, dat. ou πρός e ac. 3 esforçar-se por; batalhar para, inf. 4 Jur. debater; defender; sustentar; contestar 5 Dram. representar; interpretar. 〈ἀγών〉</p></section></article>\n<article id=\"entry-dgp-432\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγώνιος, ος, ον</h1><div class=\"entry-meta\"><span>DGP · ordem 432 na letra α · nº geral 432</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 próprio dos jogos; competitivo 2 que preside os jogos (deuses) 3 agitado; inquieto. 〈ἀγών〉</p></section></article>\n<article id=\"entry-dgp-433\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγώνισις, εως (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 433 na letra α · nº geral 433</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">luta; combate. 〈ἀγωνίζομαι〉</p></section></article>\n<article id=\"entry-dgp-434\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγώνισμα, ατος (τό)</h1><div class=\"entry-meta\"><span>DGP · ordem 434 na letra α · nº geral 434</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 exercício; luta 2 êxito 3 façanha; proeza 3 exercício de manejo; exercício literário 4 Dram. declamação; representação 5 objeto de contenda. 〈ἀγωνίζομαι〉</p></section></article>\n<article id=\"entry-dgp-435\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνισμός, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 435 na letra α · nº geral 435</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">luta. 〈ἀγωνίζομαι〉</p></section></article>\n<article id=\"entry-dgp-436\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνιστέον</h1><div class=\"entry-meta\"><span>DGP · ordem 436 na letra α · nº geral 436</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adj. verb. de ἀγωνίζομαι.</p></section></article>\n<article id=\"entry-dgp-437\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνιστής, οῦ (ὁ)</h1><div class=\"entry-meta\"><span>DGP · ordem 437 na letra α · nº geral 437</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 competidor; atleta 2 advogado; orador 3 ator 4 mestre em uma arte ou ciência. 〈ἀγωνίζομαι〉</p></section></article>\n<article id=\"entry-dgp-438\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνιστικός, ή, όν</h1><div class=\"entry-meta\"><span>DGP · ordem 438 na letra α · nº geral 438</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">1 relativo a contenda; agonístico 2 pró­prio para discussão (estilo) 3 surpreendente; excelente; eficaz 4 amante da discussão ♦ ἡ ἀγωνιστική, τὸ ἀγωνιστικόν 5 a arte de lutar. 〈ἀγωνίζομαι〉</p></section></article>\n<article id=\"entry-dgp-439\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνιστικῶς</h1><div class=\"entry-meta\"><span>DGP · ordem 439 na letra α · nº geral 439</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">adv. com disposição para a luta; com obstinação; vigorosamente.</p></section></article>\n<article id=\"entry-dgp-440\" class=\"entry-card\" data-dictionary=\"grego\" data-source=\"DGP\" hidden><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγωνοθεσία, ας (ἡ)</h1><div class=\"entry-meta\"><span>DGP · ordem 440 na letra α · nº geral 440</span></div></div><div class=\"source-tag\">DGP</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Definição do DGP</div><p class=\"entry-text\">função de agonóteta. 〈ἀγωνοθέτης〉</p></section></article>\n";
  d.rowsHtml = rowBase.slice(0, rowStart) + rows + rowBase.slice(rowStart);
  d.cardsHtml = cardBase.slice(0, cardStart) + cards + cardBase.slice(cardStart);
